from translation_client import TranslationClient
from translation_models import DictionaryTranslationRequest, DictionaryTranslationResponse


def translate_dictionary_values(payload: DictionaryTranslationRequest, config: dict = None) -> DictionaryTranslationResponse:
    config = config or {}
    client = TranslationClient(project_id=config.get('project_id'), location=config.get('location'))

    keys = list(payload.dictionary.keys())
    values_to_translate = list(payload.dictionary.values())

    if not values_to_translate:
        return DictionaryTranslationResponse(
            translated_dictionary={},
            source_language=payload.source_language,
            target_language=payload.target_language,
        )

    response = client.client.translate_text(request={
        "parent": client.parent,
        "contents": values_to_translate,
        "mime_type": "text/plain",
        "source_language_code": payload.source_language,
        "target_language_code": payload.target_language,
    })

    translated_values = [translation.translated_text for translation in response.translations]

    translated_dictionary = dict(zip(keys, translated_values))

    return DictionaryTranslationResponse(
        translated_dictionary=translated_dictionary,
        source_language=payload.source_language,
        target_language=payload.target_language,
    )

import os
from google.cloud import aiplatform

def quality_summary(translated_text: str, original_text: str, config: dict = None) -> str:
    config = config or {}
    project_id = config.get('project_id') or os.getenv('GOOGLE_CLOUD_PROJECT')
    location = config.get('location', 'us-central1') # Vertex AI typically requires a region

    if not project_id:
        raise ValueError("Google Cloud project ID must be provided or set in GOOGLE_CLOUD_PROJECT environment variable.")

    aiplatform.init(project=project_id, location=location)

    # Using a text-bison model for summarization
    # For a more production-ready solution, consider fine-tuning or more complex prompt engineering
    model = aiplatform.preview.language_models.TextGenerationModel.from_pretrained("text-bison")

    prompt = f"""Summarize potential quality issues in the following translation. Highlight any discrepancies, awkward phrasing, or potential mistranslations.
Original Text: {original_text}
Translated Text: {translated_text}
Summary of quality issues:"""

    response = model.predict(prompt=prompt, **{
        "temperature": 0.2,
        "max_output_tokens": 256,
        "top_p": 0.8,
        "top_k": 40
    })

    return response.text
